function shopServ(id){const o=[],al=S.party.filter(c=>c.hp>0),hurtN=S.party.filter(c=>c.hp>0&&(c.hp<c.hpM||c.poison>S.T)).length;
 if(id==='forgeronne'||id==='fulbert'){for(let i=0;i<S.party.length;i++){const c=S.party[i],w=c.eq.main;if(w&&!ITEMS[w].rng&&c.sharp!==w)o.push({n:`Affûter : ${ITEMS[w].n} (${CH[c.id].n})`,d:"Puissance +1 tant que l'arme reste en main.",p:12+Math.round(ITEMS[w].p/5),f:()=>{c.sharp=w;sfx('lock');return id==='forgeronne'?"Voilà. Elle coupe un cheveu en quatre. Pas le vôtre : je tiens à mes clients.":"Passée à la meule, messire. Elle n'a jamais été si convaincante.";}});}}
 if(id==='forgeronne'||id==='tailleuse'){for(let i=0;i<S.party.length;i++){const c=S.party[i],a=c.eq.corps;if(a&&c.reinf!==a)o.push({n:`${id==='forgeronne'?'Renforcer':'Doubler'} : ${ITEMS[a].n} (${CH[c.id].n})`,d:"Protection +1 tant que l'armure est portée.",p:14+Math.round(ITEMS[a].p/5),f:()=>{c.reinf=a;sfx('lock');return id==='forgeronne'?"Rivetée deux fois. Si on vous perce là, c'est qu'on visait ailleurs.":"Doublée de toile forte. On ne voit rien, et c'est tout l'art.";}});}}
 if(id==='herboriste'||id==='barnabe'||id==='goupil'){if(hurtN)o.push({n:"Panser toute la troupe",d:"Rend la moitié de la vie de chacun et chasse le poison.",p:5*hurtN,f:()=>{for(const c of al){c.hp=Math.min(c.hpM,c.hp+Math.ceil(c.hpM/2));c.poison=0;}sfx('heal');return id==='barnabe'?"Tenez-vous tranquille. La charité pique un peu : c'est à cela qu'on la reconnaît.":id==='goupil'?"Voilà, mon petit. Ne saignez plus sur ma marchandise.":"Bandé serré. Si ça gratte, c'est que ça guérit ; si ça ne gratte plus, revenez.";}});}
 if(id==='herboriste'||id==='fulbert'||id==='rodeur'){if(has('lanterne')&&(S.oil||0)<100)o.push({n:"Remplir la lanterne",d:"La jauge d'huile remonte à plein.",p:5,f:()=>{S.oil=100;sfx('pick');return"À ras bord. Ne la penchez pas, ou alors loin de moi.";}});}
 if(id==='barnabe'){if(S.party.some(c=>c.hp>0&&c.sf<c.sfM))o.push({n:"Bénédiction des voyageurs",d:"Tout le souffle de la troupe revient.",p:10,f:()=>{for(const c of al)c.sf=c.sfM;sfx('heal');return"Allez en paix. Enfin, allez. La paix, on verra.";}});}
 if(id==='fulbert'||id==='rodeur'){const L=LV.map,un=()=>{let n=0;for(let y=0;y<MH;y++)for(let x=0;x<MW;x++)if(!LS.seen[x+','+y])n++;return n;};if(un()>MW*MH*.35)o.push({n:"Un plan des lieux",d:"Toute la carte de l'endroit est tracée, sauf ce qui est caché.",p:25,f:()=>{for(let y=0;y<MH;y++)for(let x=0;x<MW;x++){const c=LS.g[y][x];if(c!=='S'&&c!=='B')LS.seen[x+','+y]=1;}sfx('page');return id==='rodeur'?"Tracé de mémoire. Les taches, c'est l'humidité ; les croix, c'est là où il ne faut pas marcher.":"Dressé par un géomètre de l'armée. Il n'en a plus l'usage : il s'est perdu.";}});}
 if(SHS&&SHS.inn){const n=SHS.inn,pr=n.price||10;o.push({n:"Une nuit pour toute la troupe",d:"Vie et souffle au complet, poison chassé. La partie est sauvegardée.",p:pr,f:()=>{for(const c of S.party){c.hp=c.hpM;c.sf=c.sfM;c.poison=0;c.stunT=0;}sfx('heal');save('auto');return n.night||"La nuit passe sans alerte. Au matin, toute la troupe est sur pied.";}});
  if(hurtN||S.party.some(c=>c.hp>0&&c.sf<c.sfM))o.push({n:"Un repas chaud",d:"Rend un tiers de la vie et du souffle.",p:Math.max(2,Math.round(pr/3)),f:()=>{for(const c of al){c.hp=Math.min(c.hpM,c.hp+Math.ceil(c.hpM/3));c.sf=Math.min(c.sfM,c.sf+Math.ceil(c.sfM/3));}sfx('heal');return"De la soupe, du lard, du pain d'hier. Pépin en reprend. Pépin en reprend toujours.";}});}
 return o;}

