 const el2=$('shLine');if(el2){const n=Math.min(SHS.line.length,Math.floor((now-SHS.t0)/22));if(el2.dataset.n!==String(n)||el2.dataset.l!==SHS.line){el2.textContent=SHS.line.slice(0,n);el2.dataset.n=n;el2.dataset.l=SHS.line;}}}
